// Prepare email: keep only new incoming mail, drop duplicates and our own sends.
// AgentMail delivers webhooks at least once, so we dedupe on event_id.
const settings = $('Settings').first().json;
const body = $('AgentMail: new email').first().json.body || {};

if (body.event_type !== 'message.received' || !body.message) return [];

const msg = body.message;
const seen = $getWorkflowStaticData('global');
seen.events = seen.events || [];
if (body.event_id && seen.events.includes(body.event_id)) return [];
if (body.event_id) seen.events = [...seen.events.slice(-199), body.event_id];

// The payload has shown "from" as a string and as "from_" (an array); accept both.
const fromRaw = msg.from ?? (Array.isArray(msg.from_) ? msg.from_[0] : msg.from_) ?? '';
const fromEmail = (String(fromRaw).match(/<([^>]+)>/) || [null, String(fromRaw)])[1].trim().toLowerCase();
const fromName = String(fromRaw).replace(/<[^>]+>/, '').replace(/"/g, '').trim() || fromEmail;

// Ignore mail the assistant inbox sent itself (replies we approved).
if (settings.agentmail_inbox_email && fromEmail === settings.agentmail_inbox_email.toLowerCase()) return [];

return [{
  json: {
    event_id: body.event_id || '',
    inbox_id: msg.inbox_id || settings.agentmail_inbox_id,
    message_id: msg.message_id,
    thread_id: msg.thread_id || '',
    from_email: fromEmail,
    from_name: fromName,
    subject: msg.subject || '(no subject)',
  },
}];

// Build the Grok API request (xAI Responses API with a strict JSON schema).
const settings = $('Settings').first().json;
const email = $('Prepare email').first().json;
const full = $input.first().json; // AgentMail: get message

const stripHtml = (h) => String(h || '').replace(/<style[\s\S]*?<\/style>/gi, '').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim();
// extracted_text is just the new part of a reply thread; fall back to the full text, then HTML.
let text = full.extracted_text || full.text || stripHtml(full.extracted_html || full.html) || full.preview || '';
if (text.length > 12000) text = text.slice(0, 12000) + '\n[…truncated]';

const system = settings.system_prompt.replace('{{BUSINESS_PROFILE}}', settings.business_profile);
const user = `From: ${email.from_name} <${email.from_email}>\nSubject: ${email.subject}\n\n${text}`;

return [{
  json: {
    grok_request: {
      model: settings.grok_model,
      store: false,
      input: [
        { role: 'system', content: system },
        { role: 'user', content: user },
      ],
      text: { format: { type: 'json_schema', name: 'inbox_triage', schema: settings.schema, strict: true } },
    },
  },
}];

// Read Grok's answer and decide whether to save a reply draft.
const settings = $('Settings').first().json;
const email = $('Prepare email').first().json;
const res = $input.first().json;

// Responses API: the text sits in output[].content[] of the "message" item.
const message = (res.output || []).find((o) => o.type === 'message');
const part = message && (message.content || []).find((c) => c.type === 'output_text' || typeof c.text === 'string');
let t = null;
try {
  t = JSON.parse(part ? part.text : res.output_text);
} catch (e) {
  t = null;
}
if (!t) {
  t = {
    category: 'other', urgency: 'normal', summary: 'The model reply could not be read. Open the email yourself.',
    next_action: 'Read it in the inbox', needs_reply: false, reply_subject: '', reply_body: '', missing: [], suspicious: false,
  };
}

const skip = (settings.skip_reply_for || []).includes(t.category);
const draft = Boolean(t.needs_reply && t.reply_body && !t.suspicious && !skip);
const subject = t.reply_subject || (/^re:/i.test(email.subject) ? email.subject : `Re: ${email.subject}`);

return [{
  json: {
    ...t,
    email,
    create_draft: draft,
    draft_request: draft
      ? { to: [email.from_email], subject, text: t.reply_body, in_reply_to: email.message_id, client_id: `draft-${email.event_id || email.message_id}` }
      : null,
  },
}];

// Format the Telegram notification (HTML). Buttons are added by the Telegram node when a draft exists.
const triage = $('Read Grok answer').first().json;
const draft = $input.first().json.draft_id ? $input.first().json : null;
const esc = (s) => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const LABEL = {
  urgent: '🔴 Urgent', lead: '🟢 Lead', customer_enquiry: '🔵 Customer enquiry',
  invoice: '🧾 Invoice', newsletter: '📰 Newsletter', other: '✉️ Other',
};
const e = triage.email;
const lines = [
  `<b>${LABEL[triage.category] || triage.category}</b>${triage.urgency === 'high' && triage.category !== 'urgent' ? ' · high urgency' : ''}`,
  `<b>${esc(e.from_name)}</b> — ${esc(e.subject)}`,
  '',
  esc(triage.summary),
  '',
  `<b>Next:</b> ${esc(triage.next_action)}`,
];
if (triage.suspicious) lines.push('', '⚠️ <b>Looks suspicious.</b> No reply was drafted. Check the sender before acting.');
if (draft) {
  const preview = triage.reply_body.length > 700 ? triage.reply_body.slice(0, 700) + '…' : triage.reply_body;
  lines.push('', '<b>Draft reply</b> (saved in AgentMail):', `<blockquote>${esc(preview)}</blockquote>`);
  if ((triage.missing || []).length) lines.push(`Fill in first: ${esc(triage.missing.join('; '))}`);
} else if (triage.needs_reply && !triage.suspicious) {
  lines.push('', 'No draft: this category is set to skip replies.');
}

return [{
  json: {
    text: lines.join('\n').slice(0, 4000),
    draft_id: draft ? draft.draft_id : '',
    has_draft: Boolean(draft),
  },
}];

// ── Settings for approvals: keep these the same as the Settings node above ──
return [{ json: {
  agentmail_inbox_id: 'PASTE_YOUR_INBOX_ID',
  telegram_chat_id: 'PASTE_YOUR_CHAT_ID',
  agentmail_base: 'https://api.agentmail.to/v0',
} }];

// A Telegram button was pressed: work out which draft and what to do.
// Only the owner's chat can approve; anything else is ignored.
const settings = $('Settings (approval)').first().json;
const update = $('Telegram: button pressed').first().json;
const q = update.callback_query;
if (!q || !q.data) return [];

const chatId = String(q.message?.chat?.id ?? '');
if (chatId !== String(settings.telegram_chat_id)) return [];

const [action, draftId] = String(q.data).split(':');
if (!['send', 'discard'].includes(action) || !draftId) return [];

return [{
  json: {
    action,
    draft_id: draftId,
    inbox_id: settings.agentmail_inbox_id,
    query_id: q.id,
    chat_id: chatId,
    message_id: q.message?.message_id,
    original_text: q.message?.text || '',
  },
}];

// Text for the button reply and the updated Telegram message.
const b = $('Read button').first().json;
const sent = b.action === 'send';
return [{ json: { ...b, toast: sent ? 'Reply sent' : 'Draft discarded', footer: sent ? '✅ Reply sent from AgentMail.' : '🗑 Draft discarded.' } }];
